// eslint-disable
'use strict';

const logger = require('@yandex-int/yandex-logger')({
    streams: [
        {
            level: 'info',
            stream: require('@yandex-int/yandex-logger/streams/qloud')(),
        },
    ],
});

// 1. Простое сообщение
logger.info('Log message');

// 2. Логируем только ошибку
let err = new Error('Something went wrong!');
logger.error(err);

// 3. Логируем сложный объект
let entry = require('./entry');
logger.error(entry);
